---
name: Integration Weekly

on:
  schedule:
    - cron: '0 2 * * 1'
  workflow_dispatch:

concurrency:
  group: >-
    ${{ github.workflow }}-${{
      github.event_name
    }}-${{
      github.ref_name || github.sha
    }}
  cancel-in-progress: true

jobs:
  integration-weekly:
    name: "py${{ matrix.python-version }} / ${{ matrix.ansible-ref }}"
    runs-on: ubuntu-latest
    timeout-minutes: 90
    permissions:
      contents: read
    strategy:
      fail-fast: false
      # One tenant: 5 resources parallely can fail in integhration test
      max-parallel: 1
      matrix:
        include:
          - { ansible-ref: stable-2.16, python-version: "3.10" }
          - { ansible-ref: stable-2.16, python-version: "3.12" }
          - { ansible-ref: stable-2.18, python-version: "3.11" }
          - { ansible-ref: stable-2.18, python-version: "3.13" }
          - { ansible-ref: stable-2.20, python-version: "3.12" }
          - { ansible-ref: stable-2.20, python-version: "3.14" }
          - { ansible-ref: devel, python-version: "3.13" }
    env:
      OCI_TEST_COMPARTMENT_ID: ${{ secrets.OCI_TEST_COMPARTMENT_ID }}
      OCI_TENANCY_ID: ${{ secrets.OCI_TENANCY_ID }}
      OCI_USER_ID: ${{ secrets.OCI_USER_ID }}
      OCI_REGION: ${{ vars.OCI_REGION }}
      OCI_USER_FINGERPRINT: ${{ secrets.OCI_USER_FINGERPRINT }}
      OCI_USER_KEY_CONTENT: ${{ secrets.OCI_USER_KEY_CONTENT }}
      OCI_CONFIG_PROFILE: ${{ vars.OCI_CONFIG_PROFILE }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with:
          persist-credentials: false

      - name: Run OCI integration workflow
        uses: ./.github/actions/run-oci-integration
        with:
          ansible-ref: ${{ matrix.ansible-ref }}
          python-version: ${{ matrix.python-version }}

  integration-weekly-check:
    if: always()
    needs:
      - integration-weekly
    runs-on: ubuntu-latest
    permissions: {}
    steps:
      - name: Decide whether the needed jobs succeeded or failed
        uses: re-actors/alls-green@b5b5b37504aa4183270bd3d855c52a67f212be35 # release/v1
        with:
          jobs: ${{ toJSON(needs) }}
